cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring; python3 - <<'EOF'
p='src/main/java/net/officefloor/hq/app/snapshot/PersonSnapshotService.java'
s=open(p).read()
s=s.replace("""    /** Move the person's snapshots to another person, on another sheet (a merge or transfer). */
    @Transactional
    public void move(String fromSheetId, Long fromPersonId, String toSheetId, Long toPersonId) {
        snapshots.findBySheetIdAndPersonIdOrderByIdAsc(fromSheetId, fromPersonId)
                .forEach(s -> s.moveTo(toSheetId, toPersonId));
        snapshots.flush();""","""    /** Move the person's snapshots to another person, on another sheet (a merge or transfer); a day the other
     *  already has a snapshot line for keeps theirs, and the moved one is dropped. */
    @Transactional
    public void move(String fromSheetId, Long fromPersonId, String toSheetId, Long toPersonId) {
        Set<LocalDate> theirs = snapshots.findBySheetIdAndPersonIdOrderByIdAsc(toSheetId, toPersonId).stream()
                .map(PersonSnapshot::getDay)
                .collect(Collectors.toSet());
        for (PersonSnapshot s : snapshots.findBySheetIdAndPersonIdOrderByIdAsc(fromSheetId, fromPersonId)) {
            if (theirs.contains(s.getDay())) {
                snapshots.delete(s);
            } else {
                s.moveTo(toSheetId, toPersonId);
            }
        }
        snapshots.flush();""")
s=s.replace("import java.util.List;\n","import java.util.List;\nimport java.util.Set;\nimport java.util.stream.Collectors;\n")
open(p,'w').write(s)
EOF
